scwin.vScrenID = "ULDINS15000.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
/********************************************** 
 * 함수명   : ins_search
 * 설명       : 주권 마스터  목록 조회한다.
 ***********************************************/
scwin.ins_search = function() {
    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_SDATE, edt_EDATE) == false) {
        return false;
    }

    // 조회버튼 비활성.
    fn_SetDisableSelectBtn(btn_search, true);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=STDCDSTKINFO_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcdstk.select.listStdCdStkInfoInquiry" + "&{P}STD_CD=" + txb_pSTD_CD.value + "&{P}ISU_KOR_NM=" + txb_pISU_KOR_NM.getValue() + "&{P}ISUR_CD=" + txb_pISUR_CD.getValue() + "&{P}ACTIV_TP_CD=" + $c.stf.getObjectValue(cmb_pACTIV_YN) + "&{P}SDATE=" + edt_SDATE.getValue() + "&{P}EDATE=" + edt_EDATE.getValue() + "&{P}FORN_COM_YN=" + $c.stf.getObjectValue(cmb_FORN_COM_YN);
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

};

/********************************************** 
 * 함수명   : ins_readCorpInfoSimbol
 * 설명       : 심볼 조회한다. 
 ***********************************************/
scwin.ins_readCorpInfoSimbol = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS05000_DETAIL_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.corpinfo.select.readCorpInfoSimbol" + "&{P}ISUR_CD=" + txb_ISUR_CD.getValue() + "&{P}COM_SYMBL=" + txb_COM_SYMBL.getValue();
    dts_Simbol.DataID = encodeURI(url);
    dts_Simbol.reset();
};

/********************************************** 
 * 함수명   : ins_detail
 * 설명       : 주권 마스터 상세 조회한다.
 ***********************************************/
scwin.ins_detail = function(STD_CD) {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=STDCDSTKINFO_VIEW_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcdstk.select.readStdCdStkInfoView" + "&{P}STD_CD=" + STD_CD;
    dts_detail.DataID = encodeURI(url);
    dts_detail.reset();
};


/********************************************** 
 * 함수명   : ins_remove
 * 설명       : 주권 삭제처리한다.
 ***********************************************/
scwin.ins_remove = function() {

    //dts_ListDelete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_ListDelete.insertRow();
    dts_ListDelete.setCellData(1, "STD_CD", txb_STD_CD.getValue());
    dts_ListDelete.setCellData(1, "ISU_NM", txb_ISU_KOR_NM.getValue());
    dts_ListDelete.setCellData(1, "CHG_RSN", txb_DEL_RSN.getValue());
    trs_remove.Action = "/StdCdStkInfoAction.do?method=removeStdCdStkInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    trs_remove.KeyName = "toinb_dataid4";
    trs_remove.KeyValue = "JSP(I:pInput=dts_ListDelete)";
    trs_remove.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_remove.Post();
};



/********************************************** 
 * 함수명   : ins_createStdCdStkInfoStdIsuNm
 * 설명       : 주권 종목명 생성 --  우선주용 
 ***********************************************/
scwin.ins_createStdCdStkInfoStdIsuNm = function() {
    dts_createStdCdStkInfoStdIsuNm.removeAll();
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=STDCDTEMP_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcd.select.createStdCdStkInfoStdIsuNm3" + "&{P}STKCERT_KIND_NM=000" + "&{P}ISUR_CD=" + txb_ISUR_CD.getValue() + "&{P}STKCERT_KIND_TP_CD=" + dts_detail.getCellData(dts_detail.getRowPosition(), "STKCERT_KIND_TP_CD") + "&{P}STD_CD_APPL_ID=" + dts_detail.getCellData(dts_detail.getRowPosition(), "STD_CD_APPL_ID");

    //alert(url); //return;
    dts_createStdCdStkInfoStdIsuNm.DataID = encodeURI(url);
    dts_createStdCdStkInfoStdIsuNm.reset();
};


/********************************************** 
 * 함수명   : ins_createStdCdStkInfoStdIsuNm000
 * 설명       : 주권 종목명 생성 -- 보통주용 
 ***********************************************/
scwin.ins_createStdCdStkInfoStdIsuNm000 = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=STDCDTEMP_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcd.select.createStdCdStkInfoStdIsuNm_000" + "&{P}STKCERT_KIND_NM=000" + "&{P}ISUR_CD=" + txb_ISUR_CD.getValue();

    // alert(url);

    dts_createStdCdStkInfoStdIsuNm.DataID = encodeURI(url);
    dts_createStdCdStkInfoStdIsuNm.reset();
};




/********************************************** 
 * 함수명   : fn_set_parAmt
 * 설명       :  무액면주식여부에 따른 액면금액 정의 
 ***********************************************/
scwin.fn_set_parAmt = function() {
    if ($c.stf.getObjectValue(ckb_NPARVALSTK_YN) == "Y") {
        edt_PAR_AMT.setValue("");
        edt_PAR_AMT.setReadOnly(true);
        edt_PAR_AMT.ReadOnlyBackColor = '#b9d4f7';
    } else {
        edt_PAR_AMT.setValue(edt_PAR_AMT1.getValue());
        edt_PAR_AMT.setReadOnly(false);
        edt_PAR_AMT.ReadOnlyBackColor = 'white';
    }
};



/********************************************** 
 * 함수명   : fn_formCheck
 * 설명       : 폼을 체크한다.
 ***********************************************/
scwin.fn_formCheck = function() {
    if (!$c.cp.isModified(dts_detail)) {
        $c.win.alert("변경된 데이터가 없습니다.");
        return false;
    }
    if (txb_simbol_chk.getValue() == "F") {
        $c.win.alert("중복된 심볼입니다.");
        txb_COM_SYMBL.focus();
        return false;
    }
    if (txb_ISUR_CD.getValue() == "" || txb_ISUR_CD.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행기관코드"));
        txb_ISUR_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_DOM_FORN_STKCERT_TP_CD) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "국내/외국주권 종류"));
        cmb_DOM_FORN_STKCERT_TP_CD.focus();
        return false;
    }
    if (txb_ISU_KOR_NM.getValue() == "" || txb_ISU_KOR_NM.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목명"));
        txb_ISU_KOR_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_KOR_NM, 80, "한글종목명")) {
        //txb_ISU_KOR_NM.value = "";
        txb_ISU_KOR_NM.focus();
        return false;
    }
    if (txb_ISU_KOR_ABBRV.getValue() == "" || txb_ISU_KOR_ABBRV.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목약명"));
        txb_ISU_KOR_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_KOR_ABBRV, 40, "한글종목약명")) {
        //txb_ISU_KOR_ABBRV.value = "";
        txb_ISU_KOR_ABBRV.focus();
        return false;
    }
    if (txb_ISU_ENG_NM.getValue() == "" || txb_ISU_ENG_NM.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목명"));
        txb_ISU_ENG_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ENG_NM, 80, "영문종목명")) {
        //txb_ISU_ENG_NM.value = "";
        txb_ISU_ENG_NM.focus();
        return false;
    }
    if (txb_ISU_ENG_ABBRV.getValue() == "" || txb_ISU_ENG_ABBRV.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목약명"));
        txb_ISU_ENG_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ENG_ABBRV, 40, "영문종목약명")) {
        //txb_ISU_ENG_ABBRV.value = "";
        txb_ISU_ENG_ABBRV.focus();
        return false;
    }

    // 복수의결권주는 존속기한, 의결권수 필수입력
    if (dts_detail.getCellData(dts_detail.getRowPosition(), "STKCERT_KIND_TP_CD") == "M") {
        if ($c.stf.getObjectValue(edt_CONTIN_DEADLINE_STRT_DD) == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "존속기한 시작일자"));
            edt_CONTIN_DEADLINE_STRT_DD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_CONTIN_DEADLINE_END_DD) == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "존속기한 종료일자"));
            edt_CONTIN_DEADLINE_END_DD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_VOTERGHT_CNT) == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "의결권수"));
            edt_VOTERGHT_CNT.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_VOTERGHT_CNT) <= 0) {
            $c.win.alert("의결권수는 0보다 큰 값을 입력하세요.");
            edt_VOTERGHT_CNT.focus();
            return false;
        }
    }
    if (fn_CheckDateObj(edt_CONTIN_DEADLINE_STRT_DD, "존속기한 시작일자")) return false;
    if (fn_CheckDateObj(edt_CONTIN_DEADLINE_END_DD, "존속기한 종료일자")) return false;
    if ($c.stf.getObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "시장구분"));
        cmb_SPOT_ISU_TRD_MKT_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_LIST_STAT_CD) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "상장여부"));
        cmb_LIST_STAT_CD.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txa_NUSUAL_ISU_COND_CONTN, 60, "특이발행조건")) {
        //txb_ISU_ENG_ABBRV.value = "";
        txa_NUSUAL_ISU_COND_CONTN.focus();
        return false;
    }

    //CFI체크
    if ($c.stf.getObjectValue(cmb_cb_p_group) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_그룹"));
        cmb_cb_p_group.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_cb_p_attr_1) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_1차속성"));
        cmb_cb_p_attr_1.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_cb_p_attr_2) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_2차속성"));
        cmb_cb_p_attr_2.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_cb_p_attr_3) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_3차속성"));
        cmb_cb_p_attr_3.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_cb_p_attr_4) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_4차속성"));
        cmb_cb_p_attr_4.focus();
        return false;
    }
};
scwin.arrPar = new Array();
/********************************************** 
 * 함수명   : fn_GetParam
 * 설명       : 전달 값을 정의한다.
 ***********************************************/
scwin.fn_GetParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue();
    scwin.arrPar[1] = txb_param2.getValue();
};


/********************************************** 
 * 함수명   : fn_Change_cfi
 * 설명       : cfi 변경 설정
 ***********************************************/
scwin.fn_Change_cfi = function() {
    // Cfi의 콤보 박스를 변경할 경우....
    var cfi = "";
    var str_cfi = dts_detail.getCellData(dts_detail.getRowPosition(), "CFI_CD");
    var temp = $c.stf.getObjectValue(cmb_cb_p_group); //선택된그룹

    //카테고리셋팅
    if (temp == "") {
        cfi = "_";
    } else if (temp == "I" || temp == "B" || temp == "E") {
        cfi = "C";
    } else {
        cfi = "E";
    }

    //그룹
    if ($c.stf.getObjectValue(cmb_cb_p_group) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_group);

    //1차속성
    if ($c.stf.getObjectValue(cmb_cb_p_attr_1) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_1);

    //2차속성
    if ($c.stf.getObjectValue(cmb_cb_p_attr_2) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_2);

    //3차속성
    if ($c.stf.getObjectValue(cmb_cb_p_attr_3) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_3);

    //4차속성
    if ($c.stf.getObjectValue(cmb_cb_p_attr_4) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_4);
    txb_CFI_CD.setValue(cfi); // cfi 설정

};


/********************************************** 
 * 함수명   : fn_set_Change
 * 설명       :  상세 조회시 CFI 상세 설정 
 ***********************************************/
scwin.fn_set_Change = function(str_cfi) {
    if (str_cfi == "") return;
    var temp = str_cfi.substring(0, 2);
    ins_cfi_set(dts_cfi_group, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "02", "E", "", "", "G");
    ins_cfi_set(dts_cfi_group_1, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "02", "C", "", "", "G");

    //하나의 데이터셋으로 합치기
    for (var i = 2; i < dts_cfi_group_1.getTotalRow() + 1; i++) {
        dts_cfi_group.insertRow();
        dts_cfi_group.setCellData(dts_cfi_group.getTotalRow(), "VALUE", dts_cfi_group_1.getCellData(i, "VALUE"));
        dts_cfi_group.setCellData(dts_cfi_group.getTotalRow(), "TEXT", dts_cfi_group_1.getCellData(i, "TEXT"));
    }
    $c.stf.setObjectValue(cmb_cb_p_group, str_cfi.substring(1, 2));
    $c.stf.setObjectValue(cmb_cb_p_attr_1, str_cfi.substring(2, 3));
    $c.stf.setObjectValue(cmb_cb_p_attr_2, str_cfi.substring(3, 4));
    $c.stf.setObjectValue(cmb_cb_p_attr_3, str_cfi.substring(4, 5));
    $c.stf.setObjectValue(cmb_cb_p_attr_4, str_cfi.substring(5, 6));
};



/********************************************** 
 * 함수명   : ins_modify
 * 설명       : 주권 표준코드  수정한다.
 ***********************************************/
scwin.ins_modify = function() {
    trs_modify.Action = "/StdCdStkInfoAction.do?method=modifyStdCdStkInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    trs_modify.KeyName = "toinb_dataid4";
    trs_modify.KeyValue = "JSP(O:pReturnOut=dts_Rst,I:pInput=dts_detail)";
    trs_modify.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_modify.Post();
};


//FISN생성
scwin.fn_make_fisn = function() {
    //alert(getObjectValue(txb_NEWSTK_ISU_TP_CONTN));
    //alert(dts_detail.NameValue(dts_detail.RowPosition,"CFI_CD"));
    var str_cfi = dts_detail.getCellData(dts_detail.getRowPosition(), "CFI_CD");
    var temp = '';
    var temp_c = str_cfi.substring(0, 1); //카테고리 cfi첫자리
    var temp_g = $c.stf.getObjectValue(cmb_cb_p_group); //선택한 그룹
    var temp_a1 = $c.stf.getObjectValue(cmb_cb_p_attr_1); //선택한 1차속성
    var temp_a2 = $c.stf.getObjectValue(cmb_cb_p_attr_2); //선택한 2차속성
    var temp_a3 = $c.stf.getObjectValue(cmb_cb_p_attr_3); //선택한 3차속성
    var temp_a4 = $c.stf.getObjectValue(cmb_cb_p_attr_4); //선택한 4차속성
    var temp_curr = $c.stf.getObjectValue(cmb_CURR_TP_CD); //선택한 발행통화

    if (temp_c == "E") {
        // E: 보통주, 우선주, 합자조합 카테고리
        if (temp_g == "S" || temp_g == "C" || temp_g == "Y" || temp_g == "M") {
            //보통주 그룹
            temp += "Com Sh";
            if (temp_a1 == "N") {
                //1차속성 무의결권(N)
                temp += " NVTG";
            }
            if (temp_a3 == "P") {
                //3차속성 부분납입(P)
                temp += " PP";
            }
            if (temp_a2 == "T") {
                //2차속성 제한있음(T)
                temp += " Rstd";
            } else if (temp_a2 == "U") {
                //2차속성 제한없음(U)
                temp += " Unrestr";
            }
            temp += " " + edt_PAR_AMT.getValue(); //액면금액

        } else if (temp_g == 'P' || temp_g == 'F') {
            //우선주 그룹
            if (temp_g == "F") {
                //그룹 전환우선주(F)
                temp += "Cv";
            } else {
                temp += "";
            }
            temp += " Pref";
        } else if (temp2 == 'L') {
            //합자조합 그룹
            temp += "Ltd Pshp";
            if (temp_a3 == "O") {
                //3차속성 무납입(O)
                temp += " Nl Pd";
            } else if (temp_a3 == "P") {
                //3차속성 부분납입(P)
                temp += " PP";
            } else if (temp_a3 == "F") {
                //3차속성 전액납입(F)
                temp += " FPd";
            }
            if (temp_curr == "1") {
                //발행통화
                temp += " KRW";
            } else if (temp_curr == "2") {
                temp += " USD";
            } else if (temp_curr == "3") {
                temp += " JPY";
            } else if (temp_curr == "4") {
                temp += " EUR";
            } else if (temp_curr == "5") {
                temp += " CNY";
            } else if (temp_curr == "6") {
                temp += " GBP";
            } else if (temp_curr == "7") {
                temp += " HKD";
            } else if (temp_curr == "8") {
                temp += " AUD";
            } else if (temp_curr == "9") {
                temp += " SGD";
            }
        }
    } else if (temp_c == 'C') {
        // C: 집합투자증권 카테고리
        if (temp_g == "B") {
            //그룹 부동산투자회사(B)
            temp += "CIV REIT";
        } else if (temp_g == "E") {
            //그룹 ETF(E)
            temp += "CIV ETF";
        } else if (temp_g == "I") {
            //그룹 증권투자회사, 선박투자회사 - 스탠다드/뮤추얼펀드(I)
            temp += "CIV";
        }
        if (temp_curr == "1") {
            //발행통화
            temp += " KRW";
        } else if (temp_curr == "2") {
            temp += " USD";
        } else if (temp_curr == "3") {
            temp += " JPY";
        } else if (temp_curr == "4") {
            temp += " EUR";
        } else if (temp_curr == "5") {
            temp += " CNY";
        } else if (temp_curr == "6") {
            temp += " GBP";
        } else if (temp_curr == "7") {
            temp += " HKD";
        } else if (temp_curr == "8") {
            temp += " AUD";
        } else if (temp_curr == "9") {
            temp += " SGD";
        }
    }

    //최종결과 FISN setting
    $c.stf.setObjectValue(txb_fisn2, temp);
};


