scwin.dts_detail_OnLoadCompleted = function(rowcount) {
    //ckb_NPARVALSTK_YN.checked = false;
    if (rowcount > 0) {
        //alert(dts_detail.NameValue(dts_detail.rowpositon,"PAR_AMT"));

        var str_cfi = dts_detail.getCellData(dts_detail.rowpositon, "CFI_CD");
        scwin.fn_set_Change(str_cfi);
        edt_PAR_AMT1.setValue(edt_PAR_AMT.getValue());

        //alert(dts_detail.NameValue(dts_detail.rowpositon,"NPARVALSTK_YN"));
        if (dts_detail.getCellData(dts_detail.rowpositon, "NPARVALSTK_YN") == "Y") {
            $c.stf.setObjectValue(ckb_NPARVALSTK_YN, "Y");
            ckb_NPARVALSTK_YN.setValue(1);
        } else {
            $c.stf.setObjectValue(ckb_NPARVALSTK_YN, "N");
            ckb_NPARVALSTK_YN.setValue(0);
        }
        scwin.fn_set_parAmt();
        fn_CtrlBtn_temp("update");
        var checkflag = false;
        if (($c.stf.getObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD) == "1" || $c.stf.getObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD) == "2" || $c.stf.getObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD) == "6") &&
            $c.stf.getObjectValue(cmb_LIST_STAT_CD) == "Y") {
            //alert( "상장종목은 수정할 수 없습니다. 공시총괄팀과 협의하시기 바랍니다."); 
            btn_modify.setDisabled(true);
            btn_modify.src = "../img/ins/btn_modify_d.gif";
            btn_delete.setDisabled(true);
            btn_delete.src = "../img/ins/btn_delete_d.gif";

            // alert 삭제 및 비밀번호 초기화도 제어 추가 20140116
            btn_clearPwd.setDisabled(true);
            btn_clearPwd.src = "../img/ins/btn_clearPwd_d.gif";
            checkflag = true;
        } else {
            btn_modify.setDisabled(false);
            btn_modify.src = "../img/ins/btn_modify.gif";
            btn_delete.setDisabled(false);
            btn_delete.src = "../img/ins/btn_delete.gif";
            btn_clearPwd.setDisabled(false);
            btn_clearPwd.src = "../img/ins/btn_clearPwd.gif";

            //checkflag = true;

        }
        if (checkflag == false) {
            if ($c.stf.getObjectValue(txb_NEWSTK_ISU_TP_CONTN) == "000") {
                // 보통주는 삭제불가   
                btn_delete.setDisabled(true);
                btn_delete.src = "../img/ins/btn_delete_d.gif";
            } else {
                btn_delete.setDisabled(false);
                btn_delete.src = "../img/ins/btn_delete.gif";
            }
        }

        /*
         * 주권종류에따른 항목 활성/비활성.(존속기한, 의결권수)
         * 보통주는 비활성, 종류주식, 복수의결권은 활성
         */
        var STKCERT_KIND_TP_CD = dts_detail.getCellData(dts_detail.getRowPosition(), "STKCERT_KIND_TP_CD");
        // 보통주
        if (STKCERT_KIND_TP_CD == "C") {
            scwin.fn_CtrlObjByStkcertKind(false);
        } else {
            scwin.fn_CtrlObjByStkcertKind(true);
        }
    } else {
        scwin.fn_set_Change("");
        fn_CtrlBtn_temp("no_data");
    }
};
