scwin.dts_createStdCdStkInfoStdIsuNm_OnLoadCompleted = function(rowcount) {
    /*
    1. 보통주 
    - 한글종목명 : 발행기관명+보통주 
    - 한글종목약명 : 발행기관명
    - 영문종목명 : 발행기관명(영)
    - 영문종목약명 : 발행기관명(영)

    2. 우선주 -- 회차는 기발급된것 + 신청중인것을 모두 고려하여 자동생성
    - 한글종목명 : 발행기관명+숫자+우선주
    - 한글종목약명 : 발행기관약명+숫자+우
    - 영문종목명 : 발행기관명(영)+(숫자P)
    - 영문종목약명 : 발행기관약명(영)+(숫자P)

    3. 복수의결권주 -- 회차는 기발급된것 + 신청중인것을 모두 고려하여 자동생성
    - 한글종목명 : 발행기관명+숫자+복수의결권주
    - 한글종목약명 : 발행기관약명+숫자+복
    - 영문종목명 : 발행기관명(영)+(숫자M)
    - 영문종목약명 : 발행기관약명(영)+(숫자M)
    */
    if (rowcount == 0) {
        $c.win.alert("해당 주권종류 코드가 존재하지 않습니다.");
        return;
    }
    txb_ISU_KOR_NM.setValue(dts_createStdCdStkInfoStdIsuNm.getCellData(1, "A"));
    txb_ISU_KOR_ABBRV.setValue(dts_createStdCdStkInfoStdIsuNm.getCellData(1, "B"));
    txb_ISU_ENG_NM.setValue(dts_createStdCdStkInfoStdIsuNm.getCellData(1, "C"));
    txb_ISU_ENG_ABBRV.setValue(dts_createStdCdStkInfoStdIsuNm.getCellData(1, "D"));
};
