scwin.cmb_cb_p_group_OnSelChange = function() {
    if ($c.stf.getObjectValue(cmb_cb_p_group) != "") {
        var str_cfi = dts_detail.getCellData(dts_detail.getRowPosition(), "CFI_CD");
        var temp1 = ""; //str_cfi.substring(0, 1);//카테고리 cfi첫자리
        var temp2 = $c.stf.getObjectValue(cmb_cb_p_group); //선택한 그룹
        var productDiv = "";
        var categoryDiv = "";

        //그룹에따라 [상품구분, 카테고리] 셋팅
        productDiv = "02";
        if (temp2 == "S" || temp2 == "C" || temp2 == "Y" || temp2 == "M") {
            //보통주, 전환보통주, 구조화증권, 기타
            categoryDiv = "E";
        } else if (temp2 == "P" || temp2 == "F") {
            //우선주, 전환우선주
            categoryDiv = "E";
        } else if (temp2 == "I" || temp2 == "B" || temp2 == "E") {
            //증권투자, 선박투자, 부동산투자, ETF
            categoryDiv = "C";
        } else if (temp2 == "L") {
            //합자조합
            categoryDiv = "E";
        }
        ins_cfi_set(dts_cfi_attr1, scwin.vScrenID, SCREN_PROCS_TP_CD_01, productDiv, categoryDiv, $c.stf.getObjectValue(cmb_cb_p_group), "1", "");
        ins_cfi_set(dts_cfi_attr2, scwin.vScrenID, SCREN_PROCS_TP_CD_01, productDiv, categoryDiv, $c.stf.getObjectValue(cmb_cb_p_group), "2", "");
        ins_cfi_set(dts_cfi_attr3, scwin.vScrenID, SCREN_PROCS_TP_CD_01, productDiv, categoryDiv, $c.stf.getObjectValue(cmb_cb_p_group), "3", "");
        ins_cfi_set(dts_cfi_attr4, scwin.vScrenID, SCREN_PROCS_TP_CD_01, productDiv, categoryDiv, $c.stf.getObjectValue(cmb_cb_p_group), "4", "");
        //alert(dts_cfi_attr1.NameValue(2,"HEAD_NM"));
        $c.stf.setObjectValue(label_attr1, "(" + dts_cfi_attr1.getCellData(2, "HEAD_NM") + ")");
        $c.stf.setObjectValue(label_attr2, "(" + dts_cfi_attr2.getCellData(2, "HEAD_NM") + ")");
        $c.stf.setObjectValue(label_attr3, "(" + dts_cfi_attr3.getCellData(2, "HEAD_NM") + ")");
        $c.stf.setObjectValue(label_attr4, "(" + dts_cfi_attr4.getCellData(2, "HEAD_NM") + ")");
    }
    scwin.fn_Change_cfi();
};
